std::vector<std::string> dependencies(const V& n){
    std::set<std::string> deps;const auto& explicitDeps=get(n,"depends_on");
    require(explicitDeps.isNull()||(explicitDeps.t==V::Arr&&explicitDeps.arr.size()<=128),"depends_on must be an array");
    for(const auto& x:explicitDeps.arr){require(x.t==V::Str&&!x.str.empty(),"invalid dependency");deps.insert(x.str);}
    const auto& d=get(n,"data");for(auto key:{"machine","stock","part","setup","tool","post","rates","slicer","fixture"})if(d.find(key))deps.insert(text(d,key));
    if(text(n,"kind")=="collision_pair"){deps.insert(text(d,"a"));deps.insert(text(d,"b"));}
    if(const auto* fixtures=d.find("fixtures")){require(fixtures->t==V::Arr&&fixtures->arr.size()<=32,"invalid fixtures");for(const auto& f:fixtures->arr){require(f.t==V::Str,"fixture reference must be text");deps.insert(f.str);}}
    return {deps.begin(),deps.end()};
}
Graph::Graph(const V& p):root(p){
    keys(p,{"name","process","nodes"});text(p,"name");auto process=text(p,"process");require(process=="cnc"||process=="fdm","process must be cnc or fdm");
    const auto& list=get(p,"nodes");require(list.t==V::Arr&&!list.arr.empty()&&list.arr.size()<=256,"plan requires 1..256 nodes");
    for(const auto& n:list.arr){keys(n,{"id","kind","name","data","depends_on"});auto id=text(n,"id");require(id.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")==std::string::npos,"node id must be portable ASCII");require(nodes.emplace(id,&n).second,"duplicate node: "+id);const auto kind=text(n,"kind");const auto& d=get(n,"data");
        if(kind=="part"){keys(d,{"feature","source_sha256"});auto f=num(d,"feature",0,9007199254740990.);require(f>=1&&f<=9007199254740990.&&f==std::floor(f),"invalid source feature");const auto digest=text(d,"source_sha256");require(digest.size()==64&&digest.find_first_not_of("0123456789abcdef")==std::string::npos,"invalid exact source hash");}
        else if(kind=="machine"){keys(d,{"min_mm","max_mm","home_mm","tool_change_mm","rapid_mm_min","tool_change_s","model"});auto lo=vec(d,"min_mm"),hi=vec(d,"max_mm");require(lo.x<hi.x&&lo.y<hi.y&&lo.z<hi.z,"machine travel must be positive");vec(d,"home_mm");vec(d,"tool_change_mm");require(num(d,"rapid_mm_min")>0&&num(d,"tool_change_s")>=0,"invalid machine speeds/times");require(text(d,"model")=="cartesian_xyz","only cartesian_xyz machine kinematics supported");}
        else if(kind=="stock"||kind=="fixture"){keys(d,{"min_mm","size_mm","resolution_mm","initially_clamped","density_kg_m3"});vec(d,"min_mm");auto size=vec(d,"size_mm");require(size.x>0&&size.y>0&&size.z>0,"stock/fixture dimensions must be positive");if(kind=="stock")require(num(d,"resolution_mm")>0,"stock resolution required");else flag(d,"initially_clamped",true);require(num(d,"density_kg_m3")>=0,"invalid stock density");}
        else if(kind=="machine_body"){keys(d,{"machine","min_mm","size_mm","axis","feature","source_sha256"});text(d,"machine");vec(d,"min_mm");auto size=vec(d,"size_mm");require(size.x>0&&size.y>0&&size.z>0,"machine body size must be positive");auto axis=text(d,"axis");require(axis=="fixed"||axis=="x"||axis=="xy"||axis=="xyz","unsupported carriage axes");if(d.find("feature")){auto f=num(d,"feature",0,9007199254740990.);require(f>=1&&f==std::floor(f),"invalid machine CAD feature");auto digest=text(d,"source_sha256");require(digest.size()==64&&digest.find_first_not_of("0123456789abcdef")==std::string::npos,"invalid machine CAD source hash");}}
        else if(kind=="collision_pair"){keys(d,{"a","b"});require(text(d,"a")!=text(d,"b"),"self-collision pair");}
        else if(kind=="tool"){keys(d,{"number","diameter_mm","cutting_length_mm","gauge_length_mm","holder_diameter_mm","holder_length_mm","kind"});const double t=num(d,"number");require(t>=1&&t<=999&&t==std::floor(t),"tool number must be 1..999");require(text(d,"kind")=="flat_end_mill","only flat_end_mill removal currently supported");for(auto k:{"diameter_mm","cutting_length_mm","gauge_length_mm","holder_diameter_mm","holder_length_mm"})require(num(d,k)>0,std::string("positive tool dimension required: ")+k);require(num(d,"gauge_length_mm")>=num(d,"cutting_length_mm"),"gauge length shorter than cutting length");require(num(d,"holder_diameter_mm")>=num(d,"diameter_mm"),"holder envelope smaller than cutter");}
        else if(kind=="setup"){keys(d,{"machine","stock","part","fixtures","origin_mm","clearance_z_mm","work_offset","setup_s"});text(d,"machine");text(d,"part");text(d,"stock");vec(d,"origin_mm");require(d.find("clearance_z_mm"),"clearance_z_mm required");num(d,"clearance_z_mm");double w=num(d,"work_offset",54);require(w>=54&&w<=59&&w==std::floor(w),"work_offset must be G54..G59");require(num(d,"setup_s")>=0,"setup time must be nonnegative");}
        else if(kind=="operation"){keys(d,{"setup","tool","post","rates","type","gcode","min_mm","size_mm","stepover_mm","stepdown_mm","feed_mm_min","plunge_mm_min","rpm","points_mm","depth_mm","fixture","duration_s","filament_diameter_mm","filament_density_kg_m3","nozzle_diameter_mm","layer_height_mm","source_path","source_sha256","source_member","source_bytes"});text(d,"setup");const auto type=text(d,"type");require(type=="gcode"||type=="face"||type=="pocket"||type=="drill"||type=="clamp"||type=="unclamp","unsupported operation type");if(type=="gcode"){if(d.find("gcode")){auto code=text(d,"gcode",true,1024*1024);require(code.find('\0')==std::string::npos,"NUL in G-code");}else{text(d,"source_path",true,4096);auto digest=text(d,"source_sha256");require(digest.size()==64&&digest.find_first_not_of("0123456789abcdef")==std::string::npos,"external program requires SHA-256");}}else if(type=="clamp"||type=="unclamp"){text(d,"fixture");require(num(d,"duration_s")>=0,"fixture event duration must be nonnegative");}else{require(process=="cnc","CAM operations require CNC process");text(d,"tool");require(num(d,"feed_mm_min")>0&&num(d,"plunge_mm_min")>0&&num(d,"rpm")>0,"CAM requires positive feed/plunge/rpm");if(type=="drill"){require(get(d,"points_mm").t==V::Arr&&!get(d,"points_mm").arr.empty()&&get(d,"points_mm").arr.size()<=128,"drill needs 1..128 points");for(const auto& point:get(d,"points_mm").arr){V wrap=V::makeObj();wrap.set("point",point);vec(wrap,"point");}}else{vec(d,"min_mm");auto size=vec(d,"size_mm");require(size.x>0&&size.y>0&&size.z>0&&num(d,"stepover_mm")>0&&num(d,"stepdown_mm")>0,"positive operation envelope and steps required");}}}
        else if(kind=="post"){keys(d,{"dialect","decimals","program_number","line_numbers"});require(text(d,"dialect")=="fanuc-3axis","unsupported post dialect");double decimals=num(d,"decimals",3),program=num(d,"program_number",1000);require(decimals>=3&&decimals<=6&&decimals==std::floor(decimals),"post decimals must be 3..6");require(program>=1&&program<=9999&&program==std::floor(program),"invalid program number");flag(d,"line_numbers");}
        else if(kind=="rates"){keys(d,{"currency","machine_hour","operator_hour","material_kg","power_kw","energy_kwh","filament_diameter_mm","filament_density_kg_m3","markup_percent"});text(d,"currency");for(auto k:{"machine_hour","operator_hour","material_kg","power_kw","energy_kwh","markup_percent"})require(num(d,k)>=0,"cost rates must be nonnegative");}
        else if(kind=="slicer"){keys(d,{"engine","executable","machine_profile","process_profile","filament_profile"});require(text(d,"engine")=="bambu-studio-cli","unsupported slicer bridge");for(auto k:{"executable","machine_profile","process_profile","filament_profile"})text(d,k,true,4096);}
        else require(false,"unknown node kind: "+kind);
    }
    std::map<std::string,int> marks;std::function<void(const std::string&)> visit=[&](const std::string& id){require(nodes.count(id),"missing dependency: "+id);require(marks[id]!=1,"cycle in manufacturing graph at "+id);if(marks[id]==2)return;marks[id]=1;for(const auto& dep:dependencies(*nodes.at(id)))visit(dep);marks[id]=2;order.push_back(id);};for(const auto& n:list.arr)visit(text(n,"id"));
    std::set<int> tools;for(const auto& [id,n]:nodes){const auto& d=get(*n,"data");if(text(*n,"kind")=="collision_pair"){for(auto key:{"a","b"}){auto ref=text(d,key);require(nodes.count(ref),"missing collision body");auto kind=text(*nodes.at(ref),"kind");require(kind=="machine_body"||kind=="fixture"||kind=="stock","collision pair requires machine_body, fixture or stock");}}if(text(*n,"kind")=="tool")require(tools.insert((int)num(d,"number")).second,"duplicate tool number");for(auto k:{"machine","stock","part","setup","tool","post","rates","slicer","fixture"})if(d.find(k))data(text(d,k),k);for(const auto& f:get(d,"fixtures").arr)data(f.str,"fixture");}
}
std::string sourceDigest(const Document& d,const V& source){auto id=(u64)num(source,"feature",0,9007199254740990.);const auto* b=body(d,id);const auto& brep=b?get(b->nativeData,"brep_base64"):get(V{},"none");require(b&&brep.t==V::Str&&!brep.str.empty(),"source requires evaluated exact B-rep");const auto& report=get(b->nativeData,"report");require(get(report,"brep_valid").t==V::Bool&&get(report,"brep_valid").b&&get(report,"solids").num==1,"source must be one valid exact solid");return iterationSha256(brep.str);}
std::string operationProgram(const Graph& g,const V& op){
    if(text(op,"type")=="gcode"){if(op.find("gcode"))return text(op,"gcode",true,1024*1024);auto code=readManufacturingProgram(text(op,"source_path",true,4096),text(op,"source_member",false,4096));require(iterationSha256(code)==text(op,"source_sha256"),"STALE_PROGRAM: external toolpath bytes changed; import and review again");return code;}
    const auto& setup=g.data(text(op,"setup"),"setup"),&machine=g.data(text(setup,"machine"),"machine"),&tool=g.data(text(op,"tool"),"tool");
    const auto type=text(op,"type");const int t=(int)num(tool,"number");const double safe=num(setup,"clearance_z_mm"),feed=num(op,"feed_mm_min"),plunge=num(op,"plunge_mm_min");auto change=vec(machine,"tool_change_mm");
    std::ostringstream out;out.imbue(std::locale::classic());out<<std::fixed<<std::setprecision(op.find("post")?(int)num(g.data(text(op,"post"),"post"),"decimals",3):6);out<<"G21 G90 G17 G94 G40\nM5\nG53 G0 Z"<<change.z<<"\nG53 G0 X"<<change.x<<" Y"<<change.y<<"\nT"<<t<<" M6\nG"<<num(setup,"work_offset",54)<<" G43 H"<<t<<"\nS"<<num(op,"rpm")<<" M3\nG0 Z"<<safe<<"\n";
    size_t moves=0;auto point=[&](double x,double y,double z,bool rapid,double f){require(++moves<=10000,"CAM path exceeds 10000 moves");out<<(rapid?"G0":"G1")<<" X"<<x<<" Y"<<y<<" Z"<<z;if(!rapid)out<<" F"<<f;out<<'\n';};
    if(type=="drill"){for(const auto& p:get(op,"points_mm").arr){const double x=p.arr[0].num,y=p.arr[1].num,z=p.arr[2].num;require(z<safe,"drill depth must be below clearance");point(x,y,safe,true,0);point(x,y,z,false,plunge);point(x,y,safe,true,0);}}
    else{const auto lo=vec(op,"min_mm"),size=vec(op,"size_mm");const double r=num(tool,"diameter_mm")/2,step=num(op,"stepover_mm"),dz=num(op,"stepdown_mm");require(step<=2*r,"stepover exceeds cutter diameter");require(type=="face"||(size.x>=2*r&&size.y>=2*r),"pocket envelope narrower than cutter");require(lo.z+size.z<safe,"stock top must be below clearance");const double xmin=type=="face"?lo.x-r:lo.x+r,xmax=type=="face"?lo.x+size.x+r:lo.x+size.x-r,ystart=type=="face"?lo.y:lo.y+r,yspan=type=="face"?size.y:size.y-2*r;const double layerCount=std::ceil(size.z/dz),rowCount=std::ceil(yspan/step);require(layerCount>=1&&layerCount<=1000&&rowCount>=0&&rowCount<=1000&&layerCount*(rowCount+1)*3<10000,"CAM subdivision capacity exceeded");const int layers=(int)layerCount,rows=(int)rowCount;for(int layer=1;layer<=layers;++layer){double z=std::max(lo.z,lo.z+size.z-layer*dz);double x=xmin;point(x,ystart,safe,true,0);point(x,ystart,z,false,plunge);for(int row=0;row<=rows;++row){const double y=ystart+std::min(yspan,row*step);point(x,y,z,false,feed);x=(row%2==0)?xmax:xmin;point(x,y,z,false,feed);}point(x,ystart+yspan,safe,true,0);}}
    out<<"G0 Z"<<safe<<"\nM5\nM9\nG53 G0 Z"<<change.z<<"\nG53 G0 X"<<change.x<<" Y"<<change.y<<"\n";return out.str();
}
